    const tcl = /^tclose:(\d+)$/.exec(data); if (tcl) { if (role === 'director') out.push({ json: { kind: 'taskaction', action: 'close', task_id: Number(tcl[1]), ...base } }); else out.push({ json: { kind: 'command', cmd: 'not_director', ...base } }); continue; }
